export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);
  const t = time;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;
  const gateOpen = t >= apexTime;
  const dropTime = gateOpen ? t - apexTime : 0;
  const dropHeight = gateOpen ? apexHeight - 0.5 * gravity * dropTime * dropTime : apexHeight;
  const dropVelocity = gateOpen ? -gravity * dropTime : 0;
  const dropAcceleration = gateOpen ? -gravity : 0;

  let tossState = "At launch";
  if (t > 0.05 && t < apexTime - 0.05) tossState = "Rising";
  else if (t >= apexTime - 0.05 && t <= apexTime + 0.05) tossState = "At the top";
  else if (t > apexTime + 0.05 && tossedHeight > 0.05) tossState = "Falling";
  else if (t >= apexTime + 0.05 && tossedHeight <= 0.05) tossState = "At launch height";

  let dropState = "Held in place";
  if (gateOpen && dropTime < 0.05) dropState = "Just released";
  else if (gateOpen && dropHeight > 0.05) dropState = "Falling together";
  else if (gateOpen && dropHeight <= 0.05) dropState = "At launch height";

  const scaleY = 120;
  const originY = 320;
  const tossX = 180;
  const dropX = 460;

  const toScreenY = (h) => originY - h * scaleY;

  const objects = [];

  objects.push(...sdk.panel({ x: 40, y: 40, w: 260, h: 360, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 40, w: 260, h: 360, title: "Drop lane", state: dropState, id: "lane.drop" }));

  const tossY = toScreenY(Math.max(0, tossedHeight));
  const dropScreenY = toScreenY(Math.max(0, dropHeight));

  objects.push(sdk.circle("ball.toss", tossX, tossY, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX, dropScreenY, 28, { role: "output" }));

  objects.push(sdk.groundMark("mark.toss", tossX, originY, 40, "0 m"));
  objects.push(sdk.groundMark("mark.drop", dropX, originY, 40, "0 m"));

  if (!gateOpen) {
    objects.push(...sdk.gate("gate", dropX, toScreenY(apexHeight), { open: false, w: 40, label: "Gate" }));
  } else {
    objects.push(...sdk.gate("gate", dropX, toScreenY(apexHeight), { open: true, w: 40, label: "Gate" }));
  }

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 20, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 20, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: 5, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 20, y: dropScreenY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 20, y: dropScreenY }, { value: dropAcceleration, direction: "up" }, { scale: 5, label: "a" }));

  objects.push(...sdk.callout(tossX + 45, tossY - 20, [`v: ${tossedVelocity.toFixed(2)} m/s`, `a: ${tossedAcceleration.toFixed(1)} m/s^2`], { id: "callout.toss" }));
  objects.push(...sdk.callout(dropX + 45, dropScreenY - 20, [`v: ${dropVelocity.toFixed(2)} m/s`, `a: ${dropAcceleration.toFixed(1)} m/s^2`], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
